.text
    la s0, pos
    li s1, 27                  # N
    li s2, 4                  # REPEATS
    li t0, 0x3F800000
    fmv.w.x f21, t0            # 1.0
    li t0, 0x40800000
    fmv.w.x f20, t0            # 4.0
rep_loop:
    fmv.w.x f10, zero          # E = 0
    li t1, 0                   # i
    mv t3, s0                  # &pos[i]
i_loop:
    flw f0, 0(t3)
    flw f1, 4(t3)
    flw f2, 8(t3)
    addi t2, t1, 1             # j = i + 1
    addi t4, t3, 12            # &pos[j]
    bge t2, s1, i_next
j_loop:
    flw f3, 0(t4)
    flw f4, 4(t4)
    flw f5, 8(t4)
    fsub.s f3, f0, f3          # dx
    fsub.s f4, f1, f4          # dy
    fsub.s f5, f2, f5          # dz
    fmul.s f6, f3, f3
    fmul.s f7, f4, f4
    fadd.s f6, f6, f7
    fmul.s f7, f5, f5
    fadd.s f6, f6, f7          # r2
    fdiv.s f7, f21, f6         # inv = 1 / r2
    fmul.s f8, f7, f7
    fmul.s f8, f8, f7          # s6
    fmul.s f9, f8, f8          # s12
    fsub.s f9, f9, f8          # s12 - s6
    fmul.s f9, f20, f9         # v = 4 * (s12 - s6)
    fadd.s f10, f10, f9        # E += v
    addi t2, t2, 1
    addi t4, t4, 12
    blt t2, s1, j_loop
i_next:
    addi t1, t1, 1
    addi t3, t3, 12
    blt t1, s1, i_loop
    addi s2, s2, -1
    bnez s2, rep_loop
    li a0, 0
    li a7, 10                  # exit
    ecall
